package com.shopsphere.model;import jakarta.persistence.*;import jakarta.validation.constraints.*;@Entity public class Product{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@NotBlank @Column(nullable=false)private String name;@NotBlank @Column(nullable=false)private String category;@NotNull @DecimalMin("0.0")private Double price;@NotNull @Min(0)private Integer stock;@Column(length=1200)private String description;public Product(){}public Long getId(){return id;}public String getName(){return name;}public void setName(String x){name=x;}public String getCategory(){return category;}public void setCategory(String x){category=x;}public Double getPrice(){return price;}public void setPrice(Double x){price=x;}public Integer getStock(){return stock;}public void setStock(Integer x){stock=x;}public String getDescription(){return description;}public void setDescription(String x){description=x;}}